DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929114059_RestoreStudentName') THEN
    UPDATE "Students"
    SET "Name" = TRIM(
