DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929122600_SplitStudentName') THEN
    ALTER TABLE "Students" ADD "FirstName" character varying(100);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929122600_SplitStudentName') THEN
    ALTER TABLE "Students" ADD "LastName" character varying(100);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929122600_SplitStudentName') THEN
    UPDATE "Students"
    SET
        "FirstName" = CASE
            WHEN POSITION(' ' IN TRIM("Name")) > 0
            THEN LEFT(TRIM("Name"), POSITION(' ' IN TRIM("Name")) - 1)
            ELSE TRIM("Name")
        END,

        "LastName" = CASE
            WHEN POSITION(' ' IN TRIM("Name")) > 0
            THEN SUBSTRING(
                TRIM("Name")
                FROM POSITION(' ' IN TRIM("Name")) + 1
            )
            ELSE ''
        END;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260929122600_SplitStudentName') THEN
    ALTER TABLE "Students" ALTER COLUMN "FirstName" SET NOT NULL;
    END IF;
END $EF$;

